import { PlaneGeometry, MeshBasicNodeMaterial, TextureLoader } from 'three/webgpu';
import { gsap } from 'gsap';
import { Node } from '@/primitives';

/**
 * Create a pricing badge capsule with accent edge and interactive hover/click.
 * @param {import('@/types').NodeConfig} config
 * @param {import('@/types').NodeContext} ctx
 * @returns {THREE.Mesh}
 */
export default function createNode(config, ctx) {
  const { scenePosition = [0, 0, 0], sceneRotation = [0, 0, 0], sceneScale = [1, 1, 1] } = config;

  // Texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  texture.encoding = THREE.sRGBEncoding ?? undefined; // safe fallback

  // Geometry: capsule aspect 512:320 → 1.6:1
  const width = 0.5;
  const height = width * (320 / 512); // 0.5 * 0.625 = 0.3125
  const geometry = new PlaneGeometry(width, height);

  // Material
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide, // for potential backface visibility
  });

  // Mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(scenePosition[0], scenePosition[1], scenePosition[2]);
  mesh.rotation.set(sceneRotation[0], sceneRotation[1], sceneRotation[2]);
  mesh.scale.set(sceneScale[0], sceneScale[1], sceneScale[2]);

  // Interaction state
  let hoverTween = null;
  let pressTween = null;

  // --- Handlers (attached to userData.handlers) ---
  mesh.userData.handlers = {
    /**
     * Hover: rise-in preset (y +0.15) with power3.out, 0.4s
     */
    pointerenter: (event) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: mesh.position.y + 0.15,
        duration: 0.4,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },

    pointerleave: (event) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: mesh.position.y - 0.15,
        duration: 0.4,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },

    /**
     * Click: press-down (scale 0.97, 120ms, back.out) then emit event
     */
    click: (event) => {
      if (pressTween) pressTween.kill();
      // Scale down
      pressTween = gsap.to(mesh.scale, {
        x: sceneScale[0] * 0.97,
        y: sceneScale[1] * 0.97,
        z: sceneScale[2] * 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        overwrite: 'auto',
        onComplete: () => {
          // Return to original scale
          gsap.to(mesh.scale, {
            x: sceneScale[0],
            y: sceneScale[1],
            z: sceneScale[2],
            duration: 0.12,
            ease: 'back.out(2)',
          });
        },
      });

      // Emit custom event for hub-pricing.select
      if (mesh.userData.emitter) {
        mesh.userData.emitter('hub-pricing.select', { mesh });
      }
    },
  };

  // Add a simple emitter if needed (can be set externally or via context)
  if (!mesh.userData.emitter) {
    mesh.userData.emitter = (eventName, data) => {
      // Placeholder: dispatch a custom event on the mesh itself
      const customEvent = new CustomEvent(eventName, { detail: data, bubbles: true });
      mesh.dispatchEvent(customEvent);
    };
  }

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
